import { revised, mutationBody, recordRevision } from './revisions.js';
import { AppError, text } from '@crew/shared';
import { getIssue, emitIssue } from './issues.js';
import { projectInput, workflowInput, DEFAULT_WORKFLOW } from '../../../../shared/src/schemas/project.js';
export function publicStatus(row) {
  return { id: row.id, projectId: row.project_id, name: row.name, category: row.category, position: row.position };
}
export function statusesFor(db, projectId) {
  return db.prepare('SELECT * FROM project_statuses WHERE project_id=? ORDER BY position,id').all(projectId).map(publicStatus);
}
export function workflowUsage(db, projectId) {
  return db.prepare(`SELECT s.id AS statusId,COUNT(i.id) AS issueCount FROM project_statuses s
    LEFT JOIN issues i ON i.status_id=s.id WHERE s.project_id=? GROUP BY s.id ORDER BY s.position,s.id`).all(projectId);
}
export function publicProject(db, row) {
  return revised({
    id: row.id,
    orgId: row.org_id,
    key: row.key,
    name: row.name,
    description: row.description,
    archived: Boolean(row.archived),
    nextIssueNumber: row.next_issue_number,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    statuses: statusesFor(db, row.id),
    workflowUsageRevision: recordRevision(workflowUsage(db, row.id))
  });
}
export function registerProjects(ctx) {
  const { app, db, requireAuth, permissions } = ctx;
  function row(id) {
    const value = db.prepare('SELECT * FROM projects WHERE id=?').get(id);
    if (!value) throw new AppError('NOT_FOUND', 'Project not found', 404);
    return value;
  }
  function emit(req, project, action, before, after) {
    ctx.bus.emit({
      actorId: req.user.id, orgId: project.org_id, projectId: project.id,
      entityType: 'project', entityId: project.id, action,
      before: before ?? null, after: after ?? null, time: ctx.now()
    });
  }
  function ensureKey(orgId, key, exceptId = '') {
    if (db.prepare('SELECT id FROM projects WHERE org_id=? AND key=? AND id<>?').get(orgId, key, exceptId)) {
      throw new AppError('CONFLICT', 'This organization already has a project with that key', 409);
    }
  }
  function writeWorkflow(projectId, statuses) {
    const current = statusesFor(db, projectId);
    const known = new Set(current.map(status => status.id));
    for (const status of statuses) {
      if (status.id && !known.has(status.id)) throw new AppError('VALIDATION', 'Status does not belong to this project', 422, { statuses: status.id });
    }
    const kept = new Set(statuses.map(status => status.id).filter(Boolean));
    const removed = current.filter(status => !kept.has(status.id));
    const hasIssues = db.prepare("SELECT 1 FROM sqlite_master WHERE type='table' AND name='issues'").get();
    for (const status of removed) {
      if (hasIssues && db.prepare('SELECT 1 FROM issues WHERE status_id=? LIMIT 1').get(status.id)) {
        throw new AppError('CONFLICT', 'Move issues out of a status before removing it', 409, { statusId: status.id });
      }
    }
    db.prepare('UPDATE project_statuses SET position=position+100000 WHERE project_id=?').run(projectId);
    for (const status of removed) db.prepare('DELETE FROM project_statuses WHERE id=?').run(status.id);
    const pendingName = '__pending_' + ctx.id() + '_';
    current.forEach((status, index) => {
      if (kept.has(status.id)) db.prepare('UPDATE project_statuses SET name=? WHERE id=?').run(pendingName + index, status.id);
    });
    statuses.forEach((status, position) => {
      if (status.id) {
        db.prepare('UPDATE project_statuses SET name=?,category=?,position=? WHERE id=?').run(status.name, status.category, position, status.id);
      } else {
        db.prepare('INSERT INTO project_statuses VALUES (?,?,?,?,?)').run(ctx.id(), projectId, status.name, status.category, position);
      }
    });
  }
  function workflowIssueState(projectId) {
    return db.prepare('SELECT id FROM issues WHERE project_id=?').all(projectId).map(row => getIssue(ctx, row.id));
  }
  function emitWorkflowIssues(req, snapshots) {
    for (const before of snapshots) {
      const after = getIssue(ctx, before.id);
      if (before.statusName !== after.statusName || before.statusCategory !== after.statusCategory) {
        emitIssue(ctx, req, 'workflow_updated', before, after);
      }
    }
  }
  function list(req, orgId) {
    permissions.scope(req, 'project:read');
    if (orgId) permissions.assertOrg(req, orgId, 'org:read');
    const rows = orgId
      ? db.prepare('SELECT * FROM projects WHERE org_id=? ORDER BY created_at,id').all(orgId)
      : db.prepare('SELECT p.* FROM projects p JOIN memberships m ON m.org_id=p.org_id WHERE m.user_id=? ORDER BY p.created_at,p.id').all(req.user.id);
    const allowed = rows.filter(project => permissions.canProject(req.user.id, project.id, 'project:read'));
    const q = text(req.query.q ?? '', 'q', { min: 0, max: 200 }).toLowerCase();
    const visible = allowed.filter(project => !q || (project.key + ' ' + project.name).toLowerCase().includes(q)).filter(project => req.query.archived === 'all' || Boolean(project.archived) === (req.query.archived === 'true'));
    return ctx.paginate(visible.map(project => publicProject(db, project)), req.query);
  }
  app.get('/api/v1/projects', requireAuth, (req, res) => res.json(list(req, req.query.orgId)));
  app.get('/api/v1/orgs/:orgId/projects', requireAuth, (req, res) => res.json(list(req, req.params.orgId)));
  app.post('/api/v1/orgs/:orgId/projects', requireAuth, (req, res) => {
    const { orgId } = req.params;
    permissions.assertOrg(req, orgId, 'project:manage');
    const input = projectInput(req.body);
    ensureKey(orgId, input.key);
    const id = ctx.id();
    const time = ctx.now();
    const project = ctx.transaction(() => {
      db.prepare('INSERT INTO projects (id,org_id,key,name,description,archived,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?)')
        .run(id, orgId, input.key, input.name, input.description, Number(input.archived ?? false), time, time);
      writeWorkflow(id, input.statuses ?? DEFAULT_WORKFLOW);
      return publicProject(db, row(id));
    });
    emit(req, row(id), 'created', null, project);
    res.status(201).json({ project });
  });
  app.get('/api/v1/projects/:projectId', requireAuth, (req, res) => {
    const project = permissions.assertProject(req, req.params.projectId, 'project:read');
    res.json({ project: publicProject(db, project), permissions: {
      manage: permissions.canProject(req.user.id, project.id, 'project:manage'),
      write: permissions.canProject(req.user.id, project.id, 'project:write')
    } });
  });
  app.patch('/api/v1/projects/:projectId', requireAuth, (req, res) => {
    const project = permissions.assertProject(req, req.params.projectId, 'project:manage');
    const before = publicProject(db, project);
    const input = projectInput(mutationBody(req.body, before), { partial: true });
    const affectedIssues = input.statuses ? workflowIssueState(project.id) : [];
    if (input.key) ensureKey(project.org_id, input.key, project.id);
    if (input.key && input.key !== project.key && project.next_issue_number > 1) {
      throw new AppError('CONFLICT', 'A project key cannot change after an issue has been numbered', 409);
    }
    const after = ctx.transaction(() => {
      db.prepare('UPDATE projects SET key=?,name=?,description=?,archived=?,updated_at=? WHERE id=?').run(
        input.key ?? project.key, input.name ?? project.name, input.description ?? project.description,
        Number(input.archived ?? Boolean(project.archived)), ctx.now(), project.id
      );
      if (input.statuses) writeWorkflow(project.id, input.statuses);
      return publicProject(db, row(project.id));
    });
    emit(req, project, 'updated', before, after);
    emitWorkflowIssues(req, affectedIssues);
    res.json({ project: after });
  });
  app.get('/api/v1/projects/:projectId/workflow', requireAuth, (req, res) => {
    const project = permissions.assertProject(req, req.params.projectId, 'project:read');
    res.json({ statuses: statusesFor(db, project.id), usage: workflowUsage(db, project.id), project: publicProject(db, project) });
  });
  app.put('/api/v1/projects/:projectId/workflow', requireAuth, (req, res) => {
    const project = permissions.assertProject(req, req.params.projectId, 'project:manage');
    const before = publicProject(db, project);
    const statuses = workflowInput(mutationBody(req.body, before));
    const affectedIssues = workflowIssueState(project.id);
    const after = ctx.transaction(() => {
      writeWorkflow(project.id, statuses);
      db.prepare('UPDATE projects SET updated_at=? WHERE id=?').run(ctx.now(), project.id);
      return publicProject(db, row(project.id));
    });
    emit(req, project, 'workflow_updated', before, after);
    emitWorkflowIssues(req, affectedIssues);
    res.json({ project: after, statuses: after.statuses });
  });
  app.delete('/api/v1/projects/:projectId', requireAuth, (req, res) => {
    const project = permissions.assertProject(req, req.params.projectId, 'project:manage');
    const before = publicProject(db, project);
    mutationBody(req.body, before);
    ctx.transaction(() => {
      db.prepare('DELETE FROM project_guests WHERE project_id=?').run(project.id);
      db.prepare('DELETE FROM projects WHERE id=?').run(project.id);
    });
    emit(req, project, 'deleted', before, null);
    res.json({ ok: true });
  });
}

import { uploadAttachment, validateUpload } from './attachment-state.js';
export function createAttachmentQueue({ issueId, maxBytes, notify = () => {}, upload = uploadAttachment, onSaved = () => {} }) {
  let entries = [];
  let serial = 0;
  let running = false;
  let disposed = false;
  let paused = false;
  let controller = null;
  let generation = 0;
  const snapshot = () => ({ entries: entries.map(entry => ({ ...entry, attempts: [...entry.attempts] })), running, paused });
  function publish() { if (!disposed) notify(snapshot()); }
  function update(id, patch) { entries = entries.map(entry => entry.id === id ? { ...entry, ...patch } : entry); publish(); }
  function add(files) {
    if (disposed || running) return;
    entries = [...entries, ...Array.from(files, file => {
      const problem = validateUpload(file, maxBytes);
      return { id: ++serial, file, status: problem ? 'invalid' : 'pending', progress: null, result: null,
        error: problem ? new Error(problem) : null, attempts: [] };
    })];
    publish();
  }
  async function start() {
    if (disposed || running) return;
    running = true; paused = false; const ticket = ++generation; publish();
    try {
      for (const entry of entries) {
        if (disposed || paused || ticket !== generation) break;
        if (entry.status !== 'pending') continue;
        controller = new AbortController();
        const ownController = controller;
        update(entry.id, { status: 'uploading', error: null, progress: { loaded: 0, total: entry.file.size } });
        const startedAt = new Date().toISOString();
        try {
          const result = await upload({ issueId, file: entry.file, signal: ownController.signal,
            onProgress(progress) { if (!disposed && ticket === generation && !ownController.signal.aborted) update(entry.id, { progress }); } });
          if (disposed || ticket !== generation) break;
          if (ownController.signal.aborted) throw Object.assign(new Error('Upload cancelled; check saved attachments before retrying.'), { code: 'CANCELLED' });
          update(entry.id, { status: 'succeeded', result: result.attachment, attempts: [...entry.attempts, { startedAt, status: 'succeeded', attachmentId: result.attachment.id }] });
          onSaved(result.attachment);
        } catch (error) {
          if (disposed || ticket !== generation) break;
          const status = ownController.signal.aborted || error.code === 'CANCELLED' ? 'cancelled' : 'failed';
          update(entry.id, { status, error, attempts: [...entry.attempts, { startedAt, status, message: error.message }] });
        } finally { if (controller === ownController) controller = null; }
      }
    } finally { if (!disposed && ticket === generation) { running = false; publish(); } }
  }
  return { snapshot, add, start,
    cancel() { paused = true; controller?.abort(); publish(); },
    remove(id) { if (!running) { entries = entries.filter(entry => entry.id !== id); publish(); } },
    clearFinished() { if (!running) { entries = entries.filter(entry => ['pending', 'uploading'].includes(entry.status)); publish(); } },
    retry(id) {
      if (disposed || running) return;
      const entry = entries.find(value => value.id === id);
      if (entry && ['failed', 'cancelled'].includes(entry.status)) update(id, { status: 'pending', error: null, progress: null });
    },
    dispose() { disposed = true; paused = true; generation++; controller?.abort(); controller = null; }
  };
}

import { useEffect, useLayoutEffect, useMemo, useRef, useState } from 'preact/hooks';
import { Button, Field, Notice, Empty } from '../../components/ui.jsx';
import { createAttachmentQueue } from './attachment-queue.js';
import { formatBytes, uploadProgress } from './attachment-state.js';
export function AttachmentQueue({ issueId, maxBytes, canWrite, onSaved, disabled, onBusy }) {
  const [saved, setSaved] = useState(null);
  const callback = useRef(onSaved); callback.current = onSaved;
  const queue = useMemo(() => createAttachmentQueue({ issueId, maxBytes, notify: state => setSaved({ queue, state }), onSaved: value => callback.current(value) }), [issueId, maxBytes]);
  const state = saved?.queue === queue ? saved.state : queue.snapshot();
  useLayoutEffect(() => () => queue.dispose(), [queue]);
  useEffect(() => { if (!canWrite) queue.cancel(); }, [queue, canWrite]);
  useEffect(() => { onBusy(state.running); return () => onBusy(false); }, [state.running]);
  const pending = state.entries.filter(entry => entry.status === 'pending').length;
  function retry(entry) {
    if (globalThis.confirm('Check the saved attachment list before retrying ' + entry.file.name + '. A lost or cancelled reply may already have saved bytes. Queue one deliberate new attempt?')) queue.retry(entry.id);
  }
  return <section aria-label="Attachment upload queue"><h3>Upload several files</h3>
    <p>Each queued file uses the same streamed upload and server hash verification. Files run sequentially. A failure is retained; retries require a deliberate choice.</p>
    <Field label="Queue attachment files"><input type="file" multiple disabled={!canWrite || disabled || state.running} onChange={event => { queue.add(event.currentTarget.files); event.currentTarget.value = ''; }} /></Field>
    <p role="status">{pending} pending · {state.entries.filter(entry => entry.status === 'succeeded').length} completed{state.paused ? ' · queue paused' : ''}</p>
    {!state.entries.length ? <Empty>No files are queued.</Empty> : <ol className="attachment-queue">{state.entries.map(entry => <li key={entry.id} data-queue-name={entry.file.name}>
      <strong>{entry.file.name}</strong> · {formatBytes(entry.file.size)} · <span data-queue-status={entry.status}>{entry.status}</span>
      {entry.progress && <p><progress max="100" value={uploadProgress(entry.progress.loaded, entry.progress.total)} aria-label={entry.file.name + ' upload progress'} /> {uploadProgress(entry.progress.loaded, entry.progress.total)}% · {formatBytes(entry.progress.loaded)} sent</p>}
      <Notice error={entry.error} />
      {entry.result && <p><a href={entry.result.downloadUrl} download={entry.result.name}>Download {entry.result.name}</a> · {formatBytes(entry.result.size)} · SHA-256 <code>{entry.result.sha256}</code></p>}
      {entry.attempts.length > 0 && <details><summary>{entry.attempts.length} attempt records</summary><ul>{entry.attempts.map((attempt, index) => <li key={index}>{attempt.startedAt} · {attempt.status}{attempt.message ? ' · ' + attempt.message : ''}</li>)}</ul></details>}
      {['failed', 'cancelled'].includes(entry.status) && <Button type="button" disabled={!canWrite || state.running || disabled} onClick={() => retry(entry)}>Queue retry for {entry.file.name}</Button>}
      <Button type="button" disabled={state.running} onClick={() => queue.remove(entry.id)}>Remove {entry.file.name} from queue</Button>
    </li>)}</ol>}
    <Button type="button" disabled={!canWrite || disabled || !pending || state.running} onClick={queue.start}>Start queued uploads</Button>
    <Button type="button" disabled={!state.running} onClick={queue.cancel}>Cancel current and pause queue</Button>
    <Button type="button" disabled={state.running || !state.entries.length} onClick={queue.clearFinished}>Clear finished queue entries</Button>
  </section>;
}

import { useRef, useState } from 'preact/hooks';
import { Page, Field, Button, Notice, Empty, Loading, useLoad } from '../../components/ui.jsx';
import { useIssuePages, PageMore } from './issue-controls.jsx';
import { usePlanningAction, PlanningRefresh } from './planning-controls.jsx';
import { AttachmentQueue } from './attachment-queue.jsx';
import { formatBytes, uploadProgress, validateUpload, uploadAttachment } from './attachment-state.js';
export function AttachmentsPanel(props) { return <AttachmentResource key={props.issueId} {...props} />; }
function AttachmentResource({ api, issueId }) {
  const [query, setQuery] = useState('');
  const route = '/issues/' + encodeURIComponent(issueId) + '/attachments';
  const attachments = useIssuePages(api, route + '?q=' + encodeURIComponent(query));
  const access = useLoad(() => api.get(route + '?limit=1'), [issueId]);
  const [file, setFile] = useState(null);
  const [progress, setProgress] = useState(null);
  const [queueBusy, setQueueBusy] = useState(false);
  const input = useRef(null);
  const action = usePlanningAction();
  const canWrite = access.data?.permissions?.write && !access.error;
  function refresh() { attachments.reload(); access.reload(); }
  async function upload(event) {
    event.preventDefault();
    if (!canWrite || queueBusy) return;
    const problem = validateUpload(file, access.data?.maxUploadBytes ?? 0);
    if (problem) { action.setError(new Error(problem)); return; }
    const selected = file;
    setProgress({ loaded: 0, total: selected.size });
    await action.run(operation => uploadAttachment({ issueId, file: selected, signal: operation.signal,
      onProgress(value) { if (operation.current()) setProgress(value); }
    }), result => {
      action.setNotice(result.attachment.name + ' uploaded: ' + formatBytes(result.attachment.size) + ', SHA-256 ' + result.attachment.sha256);
      setFile(null); setProgress(null); if (input.current) input.current.value = ''; refresh();
    });
  }
  async function remove(attachment) {
    if (!canWrite || queueBusy || !globalThis.confirm('Delete attachment ' + attachment.name + '?')) return;
    await action.run(() => api.delete('/attachments/' + attachment.id), () => {
      action.setNotice(attachment.name + ' deleted'); refresh();
    });
  }
  return <section className="panel attachments-panel" data-attachment-issue={issueId}><h2>Attachments</h2>
    <PlanningRefresh busy={action.busy} onRefresh={refresh} />
    <Notice error={action.error ?? attachments.error ?? access.error} /><Notice>{action.notice}</Notice>
    {action.error && <Button type="button" onClick={refresh}>Check saved attachments and access</Button>}
    <Field label="Find attachments"><input type="search" value={query} onInput={event => setQuery(event.currentTarget.value)} /></Field>
    {attachments.loading ? <Loading /> : !attachments.items.length ? <Empty>No attachments match this view.</Empty> : <ul className="attachments-list">
      {attachments.items.map(attachment => <li key={attachment.id}>
        <div><a href={attachment.downloadUrl} download={attachment.name}>{attachment.name}</a>
          <p>{formatBytes(attachment.size)} · {attachment.mediaType} · {new Date(attachment.createdAt).toLocaleString()}</p>
          <details><summary>SHA-256 integrity digest</summary><code className="digest">{attachment.sha256}</code></details>
        </div>
        {canWrite && <Button busy={action.busy} disabled={queueBusy} onClick={() => remove(attachment)}>Delete {attachment.name}</Button>}
      </li>)}
    </ul>}
    <PageMore list={attachments} label="attachments" />
    {!access.loading && !canWrite && <Notice>Uploads and deletion are unavailable with current attachment permissions or while this project is archived. Downloads remain subject to current project access.</Notice>}
    {canWrite && <form onSubmit={upload}>
      <p>Maximum upload: {formatBytes(access.data.maxUploadBytes)}. Bytes are streamed privately and hashed by the server.</p>
      <Field label="Attachment file"><input type="file" ref={input} disabled={action.busy || queueBusy} onChange={event => { setFile(event.currentTarget.files[0] ?? null); setProgress(null); action.setError(null); action.setNotice(''); }} /></Field>
      {file && <p>{file.name} · {formatBytes(file.size)}</p>}
      {progress && <div role="status"><progress max="100" value={uploadProgress(progress.loaded, progress.total)} aria-label="Attachment upload progress" /> {uploadProgress(progress.loaded, progress.total)}% · {formatBytes(progress.loaded)} sent for {file?.name}</div>}
      <Button busy={action.busy} disabled={!file || access.loading || queueBusy} type="submit">Upload attachment</Button>
      {action.busy && progress && <Button type="button" onClick={action.cancel}>Cancel upload</Button>}
    </form>}
    {access.data && <AttachmentQueue issueId={issueId} maxBytes={access.data.maxUploadBytes} canWrite={Boolean(canWrite)} onSaved={refresh} disabled={action.busy} onBusy={setQueueBusy} />}
  </section>;
}
export function IssueAttachmentsPage(props) { return <AttachmentPage key={props.params.issueId} {...props} />; }
function AttachmentPage({ api, params }) {
  const result = useLoad(() => api.get('/issues/' + params.issueId), [params.issueId]);
  return <Page title={result.data ? result.data.issue.key + ' attachments' : 'Issue attachments'}>
    <Notice error={result.error} /><a href={'#/issues/' + params.issueId}>Back to issue</a>
    <AttachmentsPanel api={api} issueId={params.issueId} />
  </Page>;
}

import { useEffect, useLayoutEffect, useMemo, useState } from 'preact/hooks';
import { Button, Notice } from '../../components/ui.jsx';
import { createPlanningScope } from './planning-actions.js';
export function usePlanningAction() {
  const scope = useMemo(() => createPlanningScope(), []);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);
  const [notice, setNotice] = useState('');
  useLayoutEffect(() => () => scope.dispose(), [scope]);
  async function run(execute, success) {
    const operation = scope.begin();
    if (!operation) return null;
    setBusy(true); setError(null); setNotice('');
    try {
      const value = await execute(operation);
      if (!operation.current()) return null;
      success?.(value);
      return value;
    } catch (error) {
      if (operation.current()) setError(error);
      return null;
    } finally {
      if (operation.current()) setBusy(false);
      operation.finish();
    }
  }
  return { run, busy, error, setError, notice, setNotice, cancel: scope.cancel };
}
export function usePlanningDraft(record) {
  const [base, setBase] = useState(null);
  const [draft, setDraft] = useState(null);
  const [latest, setLatest] = useState(null);
  function load(value) { setBase(value); setDraft(structuredClone(value)); setLatest(null); }
  useEffect(() => {
    if (!record) return;
    if (!base) load(record);
    else if (base.revision !== record.revision) setLatest(record);
  }, [record]);
  return { base, draft, setDraft, latest, setLatest, load,
    keep(value) { setBase(value); setLatest(null); },
    dirty: Boolean(draft && base && JSON.stringify(draft) !== JSON.stringify(base)) };
}
export function PlanningRefresh({ busy, dirty = false, selected = false, onRefresh }) {
  const [stale, setStale] = useState(false);
  useEffect(() => {
    const mark = () => setStale(true);
    window.addEventListener('focus', mark);
    return () => window.removeEventListener('focus', mark);
  }, []);
  function refresh() {
    if (selected && !globalThis.confirm('Refresh the current view and clear its selection?')) return;
    setStale(false); onRefresh();
  }
  return <aside className="planning-refresh">
    <p role="status">{stale ? 'This view may have changed while you were away. ' : ''}Live planning updates are unavailable here; refresh to check current access and saved work.</p>
    {dirty && <Notice>Your draft is retained during refresh. Inspect and explicitly load a newer saved version before replacing it.</Notice>}
    <Button type="button" disabled={busy} onClick={refresh}>Refresh planning view</Button>
  </aside>;
}

import { Page, Field, Button, Notice, Loading, useLoad } from '../../components/ui.jsx';
import { ProjectLinks, WorkflowEditor } from './projects.jsx';
import { RevisionDecision } from './issue-controls.jsx';
import { usePlanningAction, usePlanningDraft, PlanningRefresh } from './planning-controls.jsx';
import { workflowPayload } from './project-state.js';
import { WorkflowReview } from './workflow-review.jsx';
import { useState } from 'preact/hooks';
export function ProjectSettings(props) { return <SettingsResource key={props.params.projectId} {...props} />; }
function SettingsResource({ api, params, navigate }) {
  const route = '/projects/' + encodeURIComponent(params.projectId);
  const result = useLoad(() => api.get(route), [route]);
  const form = usePlanningDraft(result.data?.project);
  const action = usePlanningAction();
  const [impact, setImpact] = useState({ ready: false });
  const canManage = result.data?.permissions.manage && !result.error;
  const record = form.draft;
  async function inspect() {
    await action.run(() => api.get(route), value => form.setLatest(value.project));
  }
  function load(value) { form.load(value); action.setError(null); }
  async function save(event) {
    event.preventDefault();
    if (!canManage) return;
    if (!impact.ready) { action.setError(new Error("Review and resolve workflow impact before saving.")); return; }
    let statuses;
    try { statuses = workflowPayload(record.statuses); }
    catch (error) { action.setError(error); return; }
    await action.run(() => api.patch(route, { key: record.key, name: record.name, description: record.description,
      statuses, expectedRevision: form.base.revision }), value => {
      form.load(value.project); action.setNotice('Project and workflow saved'); result.reload();
    });
  }
  async function archive() {
    if (!canManage || !globalThis.confirm((record.archived ? 'Restore' : 'Archive') + ' this project? Unsaved fields remain local.')) return;
    await action.run(() => api.patch(route, { archived: !form.base.archived, expectedRevision: form.base.revision }), value => {
      form.setLatest(value.project); result.reload(); action.setNotice('Project lifecycle updated. Inspect the latest saved version.');
    });
  }
  async function remove() {
    if (!canManage || !globalThis.confirm('Delete this project and all its work? This cannot be undone.')) return;
    await action.run(() => api.delete(route, { expectedRevision: form.base.revision }), () => navigate('/projects'));
  }
  if (!record) return result.error ? <Notice error={result.error} /> : <Loading />;
  const problem = action.error ?? result.error;
  const latest = form.latest ?? problem?.details?.current;
  const staleError = problem ?? (latest ? new Error('Saved project settings changed. Your draft is retained.') : null);
  function update(field, value) { form.setDraft(previous => ({ ...previous, [field]: value })); }
  return <Page title={record.name + ' settings'}>
    <ProjectLinks projectId={record.id} />
    <PlanningRefresh busy={action.busy} dirty={form.dirty} onRefresh={result.reload} />
    <Notice>{action.notice}</Notice>
    <RevisionDecision error={staleError} latest={latest} busy={action.busy} onInspect={inspect} onLoad={load}
      onKeep={value => { if (globalThis.confirm('Use this saved revision as your new baseline while keeping all local fields?')) { form.keep(value); action.setError(null); } }} />
    {!canManage && <Notice>Project settings require current owner or administrator access. This draft remains visible and cannot be submitted.</Notice>}
    <form onSubmit={save} className="panel">
      <fieldset disabled={!canManage || action.busy}>
        <legend>Project details and workflow</legend>
        <Field label="Project key" name="key" value={record.key} onInput={event => update('key', event.currentTarget.value)} required maxLength={12} error={problem?.details?.key} />
        <Field label="Name" name="name" value={record.name} onInput={event => update('name', event.currentTarget.value)} required maxLength={160} error={problem?.details?.name} />
        <Field label="Description" error={problem?.details?.description}><textarea name="description" value={record.description} onInput={event => update('description', event.currentTarget.value)} rows={4} maxLength={20000} /></Field>
        <WorkflowEditor statuses={record.statuses} onChange={value => update('statuses', value)} />
        <WorkflowReview api={api} projectId={record.id} revision={form.base.revision} base={form.base.statuses} draft={record.statuses} onDecision={setImpact} />
        {Object.entries(problem?.details ?? {}).filter(([key]) => key.startsWith('statuses') || key === 'statusId').map(([key, value]) => <p role="alert" key={key}>{key}: {String(value)}</p>)}
        <Button type="submit" busy={action.busy} disabled={!form.dirty || !impact.ready}>Save project and workflow</Button>
      </fieldset>
    </form>
    <section className="panel"><h2>Project lifecycle</h2>
      <Button disabled={!canManage} busy={action.busy} onClick={archive}>{record.archived ? 'Restore project' : 'Archive project'}</Button>
      <Button disabled={!canManage} busy={action.busy} className="danger" onClick={remove}>Delete project</Button>
    </section>
  </Page>;
}

import { workflowInput } from '../../../../shared/src/schemas/project.js';
import { workflowPayload } from './project-state.js';
export function reviewWorkflow(base, draft, usage = []) {
  const counts = new Map(usage.map(item => [item.statusId, item.issueCount]));
  const known = new Set(base.map(status => status.id));
  const errors = [];
  const names = new Map();
  const ids = new Set();
  draft.forEach((status, index) => {
    const name = String(status.name ?? '').trim().toLowerCase();
    if (!name || name.length > 80) errors.push({ index, field: 'name', message: 'Use a name of 1–80 characters' });
    if (names.has(name)) {
      errors.push({ index, field: 'name', message: 'This status name is repeated' });
      errors.push({ index: names.get(name), field: 'name', message: 'This status name is repeated' });
    }
    names.set(name, index);
    if (status.id && (!known.has(status.id) || ids.has(status.id))) errors.push({ index, field: 'id', message: 'Preserve each existing status identifier once' });
    if (status.id) ids.add(status.id);
  });
  try { workflowInput({ statuses: workflowPayload(draft) }); }
  catch (error) {
    for (const [field, message] of Object.entries(error.details ?? { statuses: error.message })) errors.push({ field, message });
  }
  const rows = base.map(status => {
    const next = draft.find(item => item.id === status.id);
    return { id: status.id, name: status.name, previousCategory: status.category, nextCategory: next?.category ?? null,
      nextName: next?.name ?? null, issueCount: counts.get(status.id) ?? 0,
      removed: !next, recategorized: Boolean(next && next.category !== status.category) };
  });
  const occupiedRemoval = rows.some(row => row.removed && row.issueCount > 0);
  return { rows, errors, blocked: errors.length > 0 || occupiedRemoval,
    needsDecision: rows.some(row => row.recategorized), occupiedRemoval };
}

import { useEffect, useState } from 'preact/hooks';
import { Notice, Loading, Button, useLoad } from '../../components/ui.jsx';
import { reviewWorkflow } from './workflow-review.js';
export function WorkflowReview({ api, projectId, revision, base, draft, onDecision }) {
  const current = useLoad(() => api.get('/projects/' + projectId + '/workflow'), [projectId, revision]);
  const [accepted, setAccepted] = useState('');
  const review = reviewWorkflow(base, draft, current.data?.usage ?? []);
  const signature = JSON.stringify({ rows: review.rows, draft, revision: current.data?.project?.revision });
  const changed = current.data?.project?.revision !== revision;
  const ready = !current.loading && !current.error && !changed && !review.blocked && (!review.needsDecision || accepted === signature);
  useEffect(() => onDecision({ ready, review }), [ready, signature]);
  return <section aria-label="Workflow impact review"><h2>Workflow impact</h2>
    <p>Existing status IDs remain stable through renames and reordering. Counts describe the current saved issues; category changes update completion semantics for those issues and their sprint history.</p>
    {current.loading && <Loading />}<Notice error={current.error} />
    {changed && !current.loading && <Notice>Current workflow usage changed. Refresh the planning view, inspect the latest project, and deliberately load or keep your draft on that revision.</Notice>}
    <div className="table-scroll"><table><thead><tr><th>Status and stable ID</th><th>Current issues</th><th>Draft impact</th></tr></thead><tbody>
      {review.rows.map(row => <tr key={row.id}><td>{row.name}<br /><small>{row.id}</small></td><td>{row.issueCount}</td><td>
        {row.removed ? row.issueCount ? 'Blocked: move these issues before removing this status' : 'Remove unused status' : row.recategorized ? row.previousCategory + ' → ' + row.nextCategory : row.nextName !== row.name ? 'Rename to ' + row.nextName : 'Preserve status'}
      </td></tr>)}
    </tbody></table></div>
    {review.errors.map((error, index) => <p key={index} role="alert">{error.index !== undefined ? 'Status ' + (error.index + 1) + ' ' : ''}{error.field}: {error.message}</p>)}
    {review.occupiedRemoval && <Notice>Removal is blocked while issues use this status. <a href={'#/projects/' + projectId + '/board'}>Open the board and use move or bulk status actions</a>, then refresh this draft.</Notice>}
    {review.needsDecision && <label><input type="checkbox" checked={accepted === signature} onChange={event => setAccepted(event.currentTarget.checked ? signature : '')} /> I reviewed these category changes and their current issue counts.</label>}
    <Button type="button" disabled={current.loading} onClick={current.reload}>Refresh workflow impact</Button>
  </section>;
}
